CREATE TABLE public.onboarding_drafts(user_id uuid PRIMARY KEY DEFAULT auth.uid(),step integer NOT NULL DEFAULT 1 CHECK(step BETWEEN 1 AND 5),payload jsonb NOT NULL DEFAULT '{}',completed_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE ON public.onboarding_drafts TO authenticated; GRANT ALL ON public.onboarding_drafts TO service_role; ALTER TABLE public.onboarding_drafts ENABLE ROW LEVEL SECURITY; CREATE POLICY onboarding_owner ON public.onboarding_drafts FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); COMMENT ON TABLE public.onboarding_drafts IS 'Self-described practitioner preference is not an authorization role; privileges remain in protected organization role tables.';